    tokenUrl="token",
    scheme_name="oauth2_scheme",
    scopes={"scope1": "Scope 1"}
)
oauth2_scheme2 = OAuth2PasswordBearer(
    tokenUrl="token",
    scheme_name="oauth2_scheme",
    scopes={"scope2": "Scope 2"}
)

@app.get("/test1")
def test1(token: str = Security(oauth2_scheme1, scopes=["scope1"])):
    return {"message": "test1"}

@app.get("/test2")
def test2(token: str = Security(oauth2_scheme2, scopes=["scope2"])):
    return {"message": "test2"}

openapi_schema = get_openapi(
    title="Test API",
    version="1.0.0",
    routes=app.routes,
)

